 ]},
 {"clause_id": "c247", "issues": [
   {"issue": "A substitute check claim may be made \"within 40 Calendar Days\" of the mailing of the check or the statement, whichever is later, while the Part I Periodic Statement clause forbids asserting any claim about a matter shown on a statement unless notice was given within thirty Calendar Days of mailing. The two limitation periods for the same debit cannot both stand.", "type": 2, "prob": 0.25}
 ]},
 {"clause_id": "c248", "issues": [
